actions.script:
sprintList = []
const L = (text) => ec.l10n.localize(text)
// only for one who sees the project and is no client contact (impl-projects.md F111)
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
if (vis.isClient || !(vis.allProjects || Array.from(vis.visibleProjectIds || []).includes(rootWorkEffortId))) return
const settings = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: rootWorkEffortId}).call()?.settings || {}
estimateUnit = settings.WstEstimateUnit === 'points' ? 'points' : 'hours'
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const day = (value) => toMillis(value) == null ? '' : ec.l10n.format(String(toMillis(value)), 'yyyy-MM-dd')
const short = (value) => toMillis(value) == null ? '' : ec.l10n.format(String(toMillis(value)), 'MMM d')
const order = {WeInProgress: 0, WeApproved: 1, WeInPlanning: 1, WeComplete: 2, WeClosed: 2}
const statuses = ['WeInProgress', 'WeApproved', 'WeInPlanning'].concat(includeClosed ? ['WeComplete', 'WeClosed'] : [])
const rows = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', rootWorkEffortId)
        .condition('workEffortTypeEnumId', 'WetSprint').condition('statusId', 'in', statuses).list())
rows.sort((left, right) => (order[left.statusId] - order[right.statusId])
        || (order[left.statusId] === 2 ? (toMillis(right.actualCompletionDate) || 0) - (toMillis(left.actualCompletionDate) || 0)
            : (toMillis(left.estimatedStartDate) ?? Number.MAX_SAFE_INTEGER) - (toMillis(right.estimatedStartDate) ?? Number.MAX_SAFE_INTEGER))
        || String(left.workEffortId).localeCompare(String(right.workEffortId)))
for (const row of rows) {
    const capacity = estimateUnit === 'points' ? row.estimatedPoints : row.totalTimeAllowed
    const state = row.statusId === 'WeInProgress' ? 'active' : ['WeComplete', 'WeClosed'].includes(row.statusId) ? 'closed' : 'planned'
    sprintList.push({workEffortId: row.workEffortId, workEffortName: row.workEffortName || row.workEffortId, description: row.description || '',
        statusId: row.statusId, state: state, stateLabel: L({active: 'Active', planned: 'Planned', closed: 'Complete'}[state]),
        startDay: day(row.estimatedStartDate), endDay: day(row.estimatedCompletionDate),
        datesText: [short(row.estimatedStartDate), short(row.estimatedCompletionDate)].filter((part) => part).join(' – '),
        capacity: capacity == null || capacity === '' ? null : Number(String(capacity))})
}

backlog = null
const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: rootWorkEffortId, need: 'view'}).call() || {}
if (ec.message.hasError()) return
const L = (text) => ec.l10n.localize(text)
const project = access.project
const settings = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: rootWorkEffortId}).call()?.settings || {}
const unit = settings.WstEstimateUnit === 'points' ? 'points' : 'hours'
const sprintsOn = String(settings.WstModules || '').split(',').map((part) => part.trim()).includes('backlog')
const num = (value) => value == null || value === '' ? null : Number(String(value))
const fmt = (value) => value == null ? '' : ec.l10n.format(Math.round(value * 100) / 100, '#,##0.##')
const sprints = Array.from(ec.service.sync().name('ironstone.projects.PlanningServices.get#ProjectSprints').parameters({rootWorkEffortId: rootWorkEffortId}).call()?.sprintList || [])
const openSprintIds = sprints.map((sprint) => sprint.workEffortId)

// the project's tasks: parents, which have children (cancelled ones aside), names, for the leaves and the epics
// (never a confidential issue's task the user is no Owner of: HiddenItems.js)
const all = Array.from(ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js').without(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', rootWorkEffortId)
        .condition('workEffortTypeEnumId', 'WetTask')).selectField('workEffortId').selectField('parentWorkEffortId').selectField('workEffortName')
        .selectField('statusId').selectField('sequenceNum').selectField('estimatedPoints').selectField('estimatedWorkTime').limit(20000).list())
const byId = {}
const openChildren = {}
for (const row of all) {
    byId[row.workEffortId] = row
    if (row.parentWorkEffortId && row.statusId !== 'WeCancelled') openChildren[row.parentWorkEffortId] = true
}
const epicOf = (id) => {
    let at = byId[id]
    for (let guard = 0; at && at.parentWorkEffortId && byId[at.parentWorkEffortId] && guard < 1000; guard++) at = byId[at.parentWorkEffortId]
    return at && at.workEffortId !== id ? at : null
}
const sizeOf = (row) => num(unit === 'points' ? row.estimatedPoints : row.estimatedWorkTime)
const rankOf = (id) => { const rank = num(byId[id]?.sequenceNum); return rank == null ? Number.MAX_SAFE_INTEGER : rank }
const keyNumber = (id) => { const match = /(\d+)$/.exec(String(id)); return match ? Number(match[1]) : Number.MAX_SAFE_INTEGER }
const byRank = (left, right) => rankOf(left.workEffortId) - rankOf(right.workEffortId) || keyNumber(left.workEffortId) - keyNumber(right.workEffortId)

// the rows as WorkItems finds and decorates them, with the filters
const find = (list, more) => Array.from(ec.service.sync().name('ironstone.projects.WorkItemServices.find#WorkItems').parameters(Object.assign({list: list,
    rootWorkEffortId: rootWorkEffortId, text: text || null, purposeEnumId: purposeEnumId || null, assigneePartyId: assigneePartyId || null,
    labelId: labelId || null, underWorkEffortId: epicId || null, pageNoLimit: true, withCounts: false}, more || {})).call()?.rowList || [])
        .filter((row) => !componentId || row.componentId === componentId)
const shape = (row) => {
    const epic = epicOf(row.workEffortId)
    const size = sizeOf(byId[row.workEffortId] || {})
    return Object.assign({}, row, {epicId: epic ? epic.workEffortId : null, epicName: epic ? (epic.workEffortName || epic.workEffortId) : '',
        size: size, sizeText: fmt(size)})
}
const backlogList = find('open').filter((row) => !openChildren[row.workEffortId] && !(row.sprintId && openSprintIds.includes(row.sprintId)))
        .map(shape).sort(byRank)
const sprintRows = openSprintIds.length ? find('all', {sprintId: openSprintIds.join(',')}).filter((row) => row.statusId !== 'WeCancelled').map(shape) : []

// the totals of each sprint over all its items, not only the rows the filters keep
const memberships = openSprintIds.length ? Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', 'in', openSprintIds)
        .condition('workEffortAssocTypeEnumId', 'WeatSprint').conditionDate('fromDate', 'thruDate', null).list()) : []
const sprintList = sprints.map((sprint) => {
    const memberIds = memberships.filter((assoc) => assoc.workEffortId === sprint.workEffortId).map((assoc) => assoc.toWorkEffortId)
            .filter((id) => byId[id] && byId[id].statusId !== 'WeCancelled')
    let total = 0, doneSize = 0, doneCount = 0
    for (const id of memberIds) {
        const size = sizeOf(byId[id]) || 0
        total += size
        if (['WeComplete', 'WeClosed'].includes(byId[id].statusId)) { doneSize += size; doneCount++ }
    }
    const capacity = sprint.capacity
    return Object.assign({}, sprint, {itemCount: memberIds.length, doneCount: doneCount, total: Math.round(total * 100) / 100, totalText: fmt(total),
        doneText: fmt(doneSize), capacityText: capacity == null ? '' : fmt(capacity), overCapacity: capacity != null && total > capacity,
        rowList: sprintRows.filter((row) => row.sprintId === sprint.workEffortId).sort(byRank)})
})

// the filter options
const assignees = {}
const types = {}
for (const row of backlogList.concat(sprintRows)) {
    if (row.assigneePartyId) assignees[row.assigneePartyId] = String(row.assigneeText || '').split(', ')[0] || row.assigneePartyId
    if (row.purposeEnumId) types[row.purposeEnumId] = row.purposeLabel || row.purposeEnumId
}
const options = (map) => Object.keys(map).map((key) => ({value: key, label: map[key]})).sort((left, right) => String(left.label).localeCompare(String(right.label)))
const epicOptions = all.filter((row) => !row.parentWorkEffortId && openChildren[row.workEffortId] && !['WeComplete', 'WeClosed', 'WeCancelled'].includes(row.statusId)).sort(byRank)
        .map((row) => ({value: row.workEffortId, label: row.workEffortId + ' ' + (row.workEffortName || '')}))
const componentOptions = Array.from(ec.service.sync().name('ironstone.projects.WorkItemServices.get#PlanItemOptions').parameters({rootWorkEffortId: rootWorkEffortId,
    workEffortTypeEnumId: 'WetComponent'}).call()?.optionList || []).map((option) => ({value: option.key, label: option.text}))
const labelOptions = Array.from(ec.service.sync().name('ironstone.projects.WorkItemServices.get#LabelOptions').call()?.optionList || [])
        .map((option) => ({value: option.key, label: option.text}))
const typeOptions = Array.from(ec.service.sync().name('ironstone.projects.ProjectServices.get#WorkItemTypes').parameters({rootWorkEffortId: rootWorkEffortId}).call()?.offeredList || [])
        .map((type) => ({value: type.enumId, label: type.label}))
const defaults = access.canUpdate ? ec.service.sync().name('mantle.work.ProjectServices.get#SprintDefaults').parameters({rootWorkEffortId: rootWorkEffortId}).call() || {} : {}
let backlogTotal = 0
for (const row of backlogList) backlogTotal += row.size || 0
backlog = {
    project: {workEffortId: rootWorkEffortId, workEffortName: project.workEffortName || rootWorkEffortId, estimateUnit: unit,
        unitLabel: L(unit === 'points' ? 'points' : 'h'), sprintsOn: sprintsOn, severalSprints: settings.WstSeveralSprints === 'Y',
        canUpdate: !!access.canUpdate, canManage: !!access.canManage,
        isOpen: !['WeComplete', 'WeClosed', 'WeCancelled'].includes(project.statusId)},
    backlogList: backlogList, backlogTotalText: fmt(backlogTotal), sprintList: sprintList,
    filters: {assigneeOptions: options(assignees), typeOptions: typeOptions.length ? typeOptions : options(types), labelOptions: labelOptions,
        componentOptions: componentOptions, epicOptions: epicOptions},
    newSprint: {workEffortName: defaults.workEffortName || '', startDay: defaults.startDay || '', endDay: defaults.endDay || '',
        capacity: defaults.capacity != null ? String(Number(String(defaults.capacity))) : ''}
}

doneCount = 0; failedCount = 0; failures = []
ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: rootWorkEffortId, need: 'update'}).call()
if (ec.message.hasError()) return
const ids = (Array.isArray(workEffortIds) ? workEffortIds : String(workEffortIds || '').split(',')).map((id) => String(id).trim()).filter((id) => id)
if (!ids.length) { ec.message.addError(ec.l10n.localize('Choose the work items to move')); return }
let sprint = null
if (sprintWorkEffortId) {
    sprint = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', sprintWorkEffortId).one()
    if (sprint == null || sprint.workEffortTypeEnumId !== 'WetSprint' || sprint.rootWorkEffortId !== rootWorkEffortId) {
        ec.message.addError(ec.resource.expand('${sprintWorkEffortId} is not a sprint of project ${rootWorkEffortId}', '', {sprintWorkEffortId, rootWorkEffortId})); return
    }
}
let previous = previousWorkEffortId || null
const next = previous ? null : (nextWorkEffortId || null)
const rankIt = !!(previous || next)
for (const id of ids) {
    ec.message.pushErrors()
    let reason = null
    try {
        const access = ec.service.sync().name('ironstone.commons.TaskServices.get#TaskAccess').parameters({workEffortId: id, need: 'check', app: 'projects'}).call() || {}
        if (!access.visible) reason = ec.l10n.localize('not available')
        else if (access.workEffort.rootWorkEffortId !== rootWorkEffortId) reason = ec.l10n.localize('in another project')
        else if (!access.canUpdate) reason = ec.l10n.localize('you may not change it')
        else {
            ec.service.sync().name('ironstone.projects.PlanningServices.place#BacklogItem').parameters({workEffortId: id, sprintWorkEffortId: sprintWorkEffortId || null,
                previousWorkEffortId: rankIt ? previous : null, nextWorkEffortId: rankIt && !previous ? next : null, rankIt: rankIt}).requireNewTransaction(true).call()
            if (ec.message.hasError()) reason = ec.message.getErrorsString()
        }
    } catch (err) {
        reason = String(err && err.message ? err.message : err)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
    if (reason) {
        failedCount++
        failures.push({workEffortId: id, reason: reason})
        ec.logger.warn(`Backlog of ${rootWorkEffortId}: ${id} not moved: ${reason}`)
    } else {
        doneCount++
        previous = id
    }
}
const where = sprint ? (sprint.workEffortName || sprint.workEffortId) : ec.l10n.localize('the backlog')
message = doneCount === 1 && ids.length === 1 ? ec.resource.expand('${id} moved in ${where}', '', {id: ids[0], where})
        : ec.resource.expand('${count} work items moved in ${where}', '', {count: doneCount, where})
if (failedCount) message += ec.resource.expand('; ${count} not moved: ${reasons}', '', {count: failedCount,
    reasons: failures.map((failure) => failure.workEffortId + ' ' + failure.reason).join(', ')})

const open = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', workEffortId)
        .condition('workEffortAssocTypeEnumId', 'WeatSprint').conditionDate('fromDate', 'thruDate', null).list()).map((assoc) => assoc.workEffortId)
const openSprints = open.length ? Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', open)
        .condition('statusId', 'in', ['WeInPlanning', 'WeApproved', 'WeInProgress']).list()).map((row) => row.workEffortId) : []
const inTarget = sprintWorkEffortId ? openSprints.includes(sprintWorkEffortId) : !openSprints.length
if (!inTarget) {
    // to the backlog: out of its open sprint only (a membership in a completed sprint is its history)
    ec.service.sync().name('mantle.work.TaskServices.set#TaskSprint').parameters({workEffortId: workEffortId, sprintWorkEffortId: sprintWorkEffortId || null}).call()
    if (ec.message.hasError()) return
}
if (rankIt && (previousWorkEffortId || nextWorkEffortId) && previousWorkEffortId !== workEffortId && nextWorkEffortId !== workEffortId)
    ec.service.sync().name('mantle.work.TaskServices.set#TaskBacklogRank').parameters({workEffortId: workEffortId,
        previousWorkEffortId: previousWorkEffortId || null, nextWorkEffortId: nextWorkEffortId || null}).call()

sprint = null; project = null; canView = false; canUpdate = false; canManage = false
const row = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (row != null && row.workEffortTypeEnumId === 'WetSprint' && row.rootWorkEffortId) {
    const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: row.rootWorkEffortId, need: 'none'}).call() || {}
    canView = !!access.canView; canUpdate = !!access.canUpdate; canManage = !!access.canManage
    if (canView) { sprint = row.getMap(); project = access.project }
}
if (need === 'none') return
if (!canView) { ec.message.addError(ec.resource.expand('Sprint ${workEffortId} is not available', '', {workEffortId})); return }
if (need === 'update' && !canUpdate) ec.message.addError(ec.resource.expand('You are not on the team of ${name}', '', {name: project.workEffortName || project.workEffortId}))

const parseDay = (text, label) => {
    const value = text == null ? '' : String(text).trim()
    if (!value) return null
    const parsed = /^\d{4}-\d{2}-\d{2}/.test(value) ? ec.l10n.parseTimestamp(value.substring(0, 10) + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS') : null
    if (parsed == null) ec.message.addError(ec.resource.expand('${label}: not a date (${value}); use yyyy-MM-dd', '', {label: ec.l10n.localize(label), value}))
    return parsed
}
const start = parseDay(startDay, 'Start')
const end = parseDay(endDay, 'End')
if (ec.message.hasError()) return
const capacityText = capacity == null ? '' : String(capacity).trim()
if (capacityText && !(Number(capacityText) >= 0)) { ec.message.addError(ec.l10n.localize('The capacity is a number of 0 or more')); return }
if (workEffortId) {
    ec.service.sync().name('ironstone.projects.PlanningServices.get#SprintAccess').parameters({workEffortId: workEffortId, need: 'update'}).call()
    if (ec.message.hasError()) return
    ec.service.sync().name('mantle.work.ProjectServices.update#Sprint').parameters({workEffortId: workEffortId, workEffortName: workEffortName ?? null,
        description: description ?? null, estimatedStartDate: start, estimatedCompletionDate: end, capacity: capacityText}).call()
    if (ec.message.hasError()) return
    message = ec.resource.expand('${name} saved', '', {name: workEffortName || workEffortId})
    return
}
if (!rootWorkEffortId) { ec.message.addError(ec.l10n.localize('Choose the project of the sprint')); return }
ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: rootWorkEffortId, need: 'update'}).call()
if (ec.message.hasError()) return
workEffortId = ec.service.sync().name('mantle.work.ProjectServices.create#Sprint').parameters({rootWorkEffortId: rootWorkEffortId,
    workEffortName: workEffortName || null, description: description || null, estimatedStartDate: start, estimatedCompletionDate: end,
    capacity: capacityText ? Number(capacityText) : null}).call()?.workEffortId || null
if (ec.message.hasError()) return
const name = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()?.workEffortName || workEffortId
message = ec.resource.expand('${name} made: drag work items into it to plan it', '', {name})

const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#SprintAccess').parameters({workEffortId: workEffortId, need: 'update'}).call() || {}
if (ec.message.hasError()) return
const parseDay = (text) => {
    const value = text == null ? '' : String(text).trim()
    return /^\d{4}-\d{2}-\d{2}/.test(value) ? ec.l10n.parseTimestamp(value.substring(0, 10) + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS') : null
}
const out = ec.service.sync().name('mantle.work.ProjectServices.start#Sprint').parameters({workEffortId: workEffortId, description: description ?? null,
    estimatedStartDate: parseDay(startDay), estimatedCompletionDate: parseDay(endDay)}).call() || {}
if (ec.message.hasError()) return
message = ec.resource.expand('${name} started with ${count} work items', '', {name: access.sprint.workEffortName || workEffortId, count: out.itemCount || 0})

const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#SprintAccess').parameters({workEffortId: workEffortId, need: 'update'}).call() || {}
if (ec.message.hasError()) return
// carryTo: next, new, backlog, or the id of an open sprint
const choice = String(carryTo || 'next')
const named = !['next', 'new', 'backlog'].includes(choice)
const out = ec.service.sync().name('mantle.work.ProjectServices.complete#Sprint').parameters({workEffortId: workEffortId,
    carryTo: named ? 'next' : choice, carryToSprintId: named ? choice : null, newSprintName: newSprintName || null}).call() || {}
if (ec.message.hasError()) return
carriedToSprintId = out.carriedToSprintId || null
const name = access.sprint.workEffortName || workEffortId
const to = carriedToSprintId ? (ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', carriedToSprintId).one()?.workEffortName || carriedToSprintId)
        : ec.l10n.localize('the backlog')
message = ec.resource.expand('${name} complete: ${done} done', '', {name, done: out.doneCount || 0})
        + (out.notDoneCount ? ec.resource.expand(', ${count} carried over to ${to}', '', {count: (out.carriedIds || []).length, to}) : '')

ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: rootWorkEffortId, need: 'manage'}).call()
if (ec.message.hasError()) return
const own = ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('workEffortId', rootWorkEffortId).condition('settingTypeEnumId', 'WstModules').one()
const settings = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: rootWorkEffortId}).call()?.settings || {}
const modules = String((own ? own.settingValue : settings.WstModules) || '').split(',').map((part) => part.trim()).filter((part) => part)
if (!modules.includes('backlog')) modules.unshift('backlog')
ec.service.sync().name('mantle.work.ProjectServices.store#ProjectSetting').parameters({workEffortId: rootWorkEffortId, settingTypeEnumId: 'WstModules',
    settingValue: modules.join(',')}).call()
if (ec.message.hasError()) return
message = ec.l10n.localize('Sprints are on: make the first one with New sprint')

optionList = []
if (!rootWorkEffortId) return
const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: rootWorkEffortId, need: 'none'}).call() || {}
if (!access.canView) return
for (const sprint of ec.service.sync().name('ironstone.projects.PlanningServices.get#ProjectSprints').parameters({rootWorkEffortId: rootWorkEffortId}).call()?.sprintList || [])
    optionList.push({key: sprint.workEffortId, text: sprint.workEffortName + ' · ' + sprint.stateLabel + (sprint.datesText ? ' · ' + sprint.datesText : '')})

detail = null
const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#SprintAccess').parameters({workEffortId: workEffortId, need: 'view'}).call() || {}
if (ec.message.hasError()) return
const L = (text) => ec.l10n.localize(text)
const sprint = access.sprint
const project = access.project
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const day = (value) => toMillis(value) == null ? '' : ec.l10n.format(String(toMillis(value)), 'yyyy-MM-dd')
const long = (value) => toMillis(value) == null ? '' : ec.l10n.format(String(toMillis(value)), 'MMM d, yyyy')
const fmt = (value) => value == null ? '' : ec.l10n.format(Math.round(Number(String(value)) * 100) / 100, '#,##0.##')
const burn = ec.service.sync().name('mantle.work.ProjectReportServices.get#SprintBurndown').parameters({workEffortId: workEffortId}).call() || {}
if (ec.message.hasError()) return
const unit = burn.estimateUnit || 'hours'
const unitLabel = L(unit === 'points' ? 'points' : 'h')
const state = sprint.statusId === 'WeInProgress' ? 'active' : ['WeComplete', 'WeClosed'].includes(sprint.statusId) ? 'closed' : 'planned'
// the items: those in it now (a completed sprint: those it ended with, carried over ones too)
const outcome = {}
for (const item of burn.itemList || []) outcome[item.workEffortId] = item.outcome
const shownIds = Array.from(burn.itemList || []).filter((item) => item.outcome !== 'removed').map((item) => item.workEffortId)
let rows = []
if (shownIds.length) {
    const tasks = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', Array.from(new Set(shownIds))).list()).map((row) => row.getMap())
    // the visibility of WorkItems: only the rows find#WorkItems would show
    const visible = new Set(Array.from(ec.service.sync().name('ironstone.projects.WorkItemServices.find#WorkItems').parameters({list: 'all', rootWorkEffortId: sprint.rootWorkEffortId,
        sprintId: state === 'closed' ? null : workEffortId, pageNoLimit: true, withCounts: false}).call()?.rowList || []).map((row) => row.workEffortId))
    const shown = state === 'closed' ? tasks.filter((task) => ec.service.sync().name('ironstone.commons.TaskServices.get#TaskAccess')
            .parameters({workEffortId: task.workEffortId, need: 'check', app: 'projects'}).call()?.visible) : tasks.filter((task) => visible.has(task.workEffortId))
    rows = Array.from(ec.service.sync().name('ironstone.projects.WorkItemServices.decorate#WorkItemRows').parameters({taskList: shown}).call()?.rowList || [])
    const sizes = {}
    for (const task of tasks) sizes[task.workEffortId] = unit === 'points' ? task.estimatedPoints : task.estimatedWorkTime
    const outcomeLabels = {done: L('Done'), carried: L('Carried over'), cancelled: L('Cancelled'), open: L('Open')}
    rows = rows.map((row) => Object.assign(row, {sizeText: fmt(sizes[row.workEffortId]), outcome: outcome[row.workEffortId] || 'open',
        outcomeLabel: outcomeLabels[outcome[row.workEffortId]] || ''}))
    const rankOf = (id) => { const task = tasks.find((one) => one.workEffortId === id); return task && task.sequenceNum != null ? Number(String(task.sequenceNum)) : Number.MAX_SAFE_INTEGER }
    rows.sort((left, right) => rankOf(left.workEffortId) - rankOf(right.workEffortId))
}
const scopeChangeList = Array.from(burn.scopeChangeList || []).map((change) => Object.assign({}, change, {changeLabel: L(change.change === 'added' ? 'Added' : 'Removed'),
    dateText: ec.l10n.format(String(change.changedDate), 'MMM d, h:mm a'), byText: change.userName || '', sizeText: fmt(change.size),
    url: '/qapps/Projects/WorkItems/WorkItemDetail?workEffortId=' + encodeURIComponent(change.workEffortId)}))
const dayList = Array.from(burn.dayList || []).map((row) => Object.assign({}, row, {label: row.start ? L('Start') : ec.l10n.format(ec.l10n.parseTimestamp(row.day + ' 12:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'), 'MMM d'),
    remainingText: row.remaining == null ? '' : fmt(row.remaining), idealText: fmt(row.ideal)}))
const sprints = Array.from(ec.service.sync().name('ironstone.projects.PlanningServices.get#ProjectSprints').parameters({rootWorkEffortId: sprint.rootWorkEffortId}).call()?.sprintList || [])
const carryOptions = sprints.filter((other) => other.workEffortId !== workEffortId).map((other) => ({key: other.workEffortId, text: other.workEffortName + ' · ' + other.stateLabel
        + (other.datesText ? ' · ' + other.datesText : '')}))
const openCount = Array.from(burn.itemList || []).filter((item) => item.outcome === 'open').length
const capacity = burn.capacity
const settings = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: sprint.rootWorkEffortId}).call()?.settings || {}
detail = {workEffortId: workEffortId, workEffortName: sprint.workEffortName || workEffortId, description: sprint.description || '',
    statusId: sprint.statusId, state: state, stateLabel: L({active: 'Active', planned: 'Planned', closed: 'Complete'}[state]),
    rootWorkEffortId: sprint.rootWorkEffortId, projectName: project.workEffortName || sprint.rootWorkEffortId,
    startDay: day(sprint.estimatedStartDate), endDay: day(sprint.estimatedCompletionDate),
    datesText: [long(sprint.estimatedStartDate), long(sprint.estimatedCompletionDate)].filter((part) => part).join(' – '),
    startedText: long(sprint.actualStartDate), completedDateText: long(sprint.actualCompletionDate),
    capacity: capacity, capacityText: capacity == null ? '' : fmt(capacity) + ' ' + unitLabel, capacityValue: capacity == null ? '' : String(capacity),
    estimateUnit: unit, unitLabel: unitLabel, canUpdate: !!access.canUpdate, canManage: !!access.canManage,
    severalSprints: settings.WstSeveralSprints === 'Y',
    committed: burn.committed, completed: burn.completed, remaining: burn.remaining, added: burn.added, removed: burn.removed,
    carriedOver: burn.carriedOver, daysLeft: burn.daysLeft, workDays: burn.workDays, itemCount: burn.itemCount, doneCount: burn.doneCount,
    committedText: fmt(burn.committed) + ' ' + unitLabel, completedText: fmt(burn.completed) + ' ' + unitLabel,
    remainingText: fmt(burn.remaining) + ' ' + unitLabel, addedText: fmt(burn.added), removedText: fmt(burn.removed), carriedText: fmt(burn.carriedOver),
    openCount: openCount, dayList: dayList, scopeChangeList: scopeChangeList, rowList: rows, carryOptions: carryOptions,
    nextSprintId: carryOptions.length ? carryOptions.find((option) => sprints.find((other) => other.workEffortId === option.key)?.state === 'planned')?.key || null : null}

plan = null; project = null; canView = false; canUpdate = false; canManage = false
const types = kind === 'milestone' ? ['WetMilestone'] : kind === 'release' ? ['WetRelease'] : ['WetMilestone', 'WetRelease']
const row = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (row != null && types.includes(row.workEffortTypeEnumId) && row.rootWorkEffortId) {
    const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: row.rootWorkEffortId, need: 'none'}).call() || {}
    canView = !!access.canView; canUpdate = !!access.canUpdate; canManage = !!access.canManage
    if (canView) { plan = row.getMap(); project = access.project }
    // a client contact: no cost of it (design-projects.md §1.1; impl-projects.md P10)
    if (plan && ec.user.hasPermission('PROJECT_CLIENT')) for (const field of ['actualCost', 'actualClientCost', 'totalClientCostAllowed', 'costUomId']) delete plan[field]
}
if (need === 'none') return
const label = ec.l10n.localize(kind === 'release' ? 'Release' : kind === 'milestone' ? 'Milestone' : 'Plan item')
if (!canView) { ec.message.addError(ec.resource.expand('${label} ${workEffortId} is not available', '', {label, workEffortId})); return }
if (need === 'update' && !canUpdate) ec.message.addError(ec.resource.expand('You are not on the team of ${name}', '', {name: project.workEffortName || project.workEffortId}))

rowList = []
const plans = Array.from(planList || [])
if (!plans.length) return
const L = (text) => ec.l10n.localize(text)
const vis = visibleInfo || ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
const managed = new Set(Array.from(vis.managedProjectIds || []))
const members = new Set(Array.from(vis.memberProjectIds || []))
const projectsManager = ec.user.isInGroup('BOSS_PROJECT_MANAGER') || ec.user.isInGroup('ADMIN')
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const day = (value) => toMillis(value) == null ? '' : ec.l10n.format(String(toMillis(value)), 'yyyy-MM-dd')
const text = (value) => toMillis(value) == null ? '' : ec.l10n.format(String(toMillis(value)), 'MMM d, yyyy')
const fmt = (value) => ec.l10n.format(Math.round(Number(value || 0) * 100) / 100, '#,##0.##')
const today = day(ec.user.nowTimestamp)
const summary = ec.service.sync().name('mantle.work.ProjectServices.get#PlanItemSummary').parameters({workEffortIdList: plans.map((plan) => plan.workEffortId)}).call()?.summaryMap || {}
const colors = ec.service.sync().name('org.moqui.ui.StatusServices.get#StatusColors').parameters({statusIdList: Array.from(new Set(plans.map((plan) => plan.statusId)))}).call()?.colors || {}
const projectIds = Array.from(new Set(plans.map((plan) => plan.rootWorkEffortId)))
const projectNames = {}
for (const row of Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', projectIds).selectField('workEffortId,workEffortName').list()))
    projectNames[row.workEffortId] = row.workEffortName || row.workEffortId
// the milestones' gates (impl-projects.md P8b): which need approval, which wait for it
const milestoneIds = plans.filter((plan) => plan.workEffortTypeEnumId === 'WetMilestone').map((plan) => plan.workEffortId)
const gated = new Set(), awaiting = new Set()
if (milestoneIds.length) {
    for (const row of ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('workEffortId', 'in', milestoneIds).condition('settingTypeEnumId', 'WstApprovalRequired')
            .condition('settingValue', 'Y').disableAuthz().list()) gated.add(row.workEffortId)
    for (const row of ec.entity.find('mantle.work.effort.WorkEffortApproval').condition('workEffortId', 'in', milestoneIds).condition('statusId', 'WeaRequested')
            .disableAuthz().list()) awaiting.add(row.workEffortId)
}
const kinds = {WetMilestone: ['milestone', 'Milestone', 'sym_o_flag', '/qapps/Projects/Projects/MilestoneDetail'], WetRelease: ['release', 'Release', 'sym_o_new_releases',
    '/qapps/Projects/Projects/ReleaseDetail'], WetSprint: ['sprint', 'Sprint', 'sym_o_sprint', '/qapps/Projects/WorkItems/SprintDetail']}
for (const plan of plans) {
    const kind = kinds[plan.workEffortTypeEnumId] || kinds.WetMilestone
    const stats = summary[plan.workEffortId] || {}
    const isOpen = !['WeComplete', 'WeClosed', 'WeCancelled'].includes(plan.statusId)
    const dueDay = day(plan.estimatedCompletionDate)
    const statusItem = ec.entity.find('moqui.basic.StatusItem').condition('statusId', plan.statusId).useCache(true).one()
    const statusLabel = plan.workEffortTypeEnumId === 'WetRelease' && plan.statusId === 'WeComplete' ? L('Released')
        : plan.workEffortTypeEnumId === 'WetMilestone' && plan.statusId === 'WeComplete' ? L('Reached') : (statusItem?.description || plan.statusId || '')
    const canUpdate = projectsManager || managed.has(plan.rootWorkEffortId) || members.has(plan.rootWorkEffortId)
    const hours = Number(stats.estimatedWorkTime || 0)
    rowList.push({workEffortId: plan.workEffortId, workEffortName: plan.workEffortName || plan.workEffortId, description: plan.description || '',
        workEffortTypeEnumId: plan.workEffortTypeEnumId, kind: kind[0], kindLabel: L(kind[1]), kindIcon: kind[2],
        url: kind[3] + '?workEffortId=' + encodeURIComponent(plan.workEffortId),
        rootWorkEffortId: plan.rootWorkEffortId, projectName: projectNames[plan.rootWorkEffortId] || plan.rootWorkEffortId,
        statusId: plan.statusId, statusLabel: statusLabel, statusColor: colors[plan.statusId] || 'grey-7', isOpen: isOpen,
        startDay: day(plan.estimatedStartDate), startText: text(plan.estimatedStartDate), dueDay: dueDay, dueText: text(plan.estimatedCompletionDate),
        allDay: 'Y', overdue: isOpen && !!dueDay && dueDay < today, reachedText: isOpen ? '' : text(plan.actualCompletionDate),
        itemCount: stats.itemCount || 0, doneCount: stats.doneCount || 0, inProgressCount: stats.inProgressCount || 0, notStartedCount: stats.notStartedCount || 0,
        percentDone: stats.percentDone || 0, progressValue: (stats.percentDone || 0) / 100,
        doneOfTotal: (stats.doneCount || 0) + ' / ' + (stats.itemCount || 0),
        hoursText: hours ? fmt(hours - Math.min(hours, Number(stats.remainingWorkTime || 0))) + ' / ' + fmt(hours) + ' h' : '',
        pointsText: stats.estimatedPoints ? fmt(stats.donePoints) + ' / ' + fmt(stats.estimatedPoints) + ' ' + L('points') : '',
        calendarTitle: (plan.workEffortName || plan.workEffortId) + ' · ' + L(kind[1]) + ' (' + plan.rootWorkEffortId + ')',
        gateRequired: gated.has(plan.workEffortId), awaitingApproval: awaiting.has(plan.workEffortId),
        canUpdate: canUpdate && plan.workEffortTypeEnumId !== 'WetSprint'})
}

service.description:
The Roadmap's find: the milestones and releases of the projects the user sees (one project with
            rootWorkEffortId; the sprints too when kind is sprint or, in a project, all), by list (upcoming: open, the default;
            overdue: open and due before today; awaiting: a milestone whose gate's approval waits; completed: Complete or Closed;
            all), kind (all, milestone, release, sprint) and
            text in the name or id; due period (dueFrom, dueThru exclusive). Sorted by project, then due date (none last); up to
            500, decorated (decorate#PlanItemRows), with the count of each list.

actions.script:
const lists = ['upcoming', 'overdue', 'awaiting', 'completed', 'all']
if (!lists.includes(list)) list = 'upcoming'
const kinds = {all: null, milestone: ['WetMilestone'], release: ['WetRelease'], sprint: ['WetSprint']}
if (!(kind in kinds)) kind = 'all'
rowList = []; counts = {}; kindCounts = {}
for (const key of lists) counts[key] = 0
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
let projectIds = null
if (rootWorkEffortId) {
    const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: rootWorkEffortId, need: 'none'}).call() || {}
    if (!access.canView) return
    projectIds = [rootWorkEffortId]
} else if (!vis.allProjects) {
    projectIds = Array.from(vis.visibleProjectIds || [])
    if (!projectIds.length) return
}
const types = rootWorkEffortId ? ['WetMilestone', 'WetRelease', 'WetSprint'] : ['WetMilestone', 'WetRelease']
let find = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortTypeEnumId', 'in', kind === 'sprint' ? ['WetSprint'] : types)
if (projectIds) find = find.condition('rootWorkEffortId', 'in', projectIds)
let rows = Array.from(find.list()).map((row) => row.getMap())
// templates are left out of every list
if (!rootWorkEffortId && rows.length) {
    const templates = new Set(Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', Array.from(new Set(rows.map((row) => row.rootWorkEffortId))))
            .condition('isTemplate', 'Y').selectField('workEffortId').list()).map((row) => row.workEffortId))
    rows = rows.filter((row) => !templates.has(row.rootWorkEffortId))
}
const words = String(text || '').trim().toLowerCase()
if (words) rows = rows.filter((row) => String(row.workEffortName || '').toLowerCase().includes(words) || String(row.workEffortId).toLowerCase().includes(words))
const toMillis = (value) => value == null || value === '' ? null : (typeof value === 'number' ? value : (/^-?\d+$/.test(String(value)) ? Number(String(value)) : Date.parse(String(value))))
if (dueFrom != null) rows = rows.filter((row) => toMillis(row.estimatedCompletionDate) != null && toMillis(row.estimatedCompletionDate) >= toMillis(dueFrom))
if (dueThru != null) rows = rows.filter((row) => toMillis(row.estimatedCompletionDate) != null && toMillis(row.estimatedCompletionDate) < toMillis(dueThru))
const today = ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
const open = (row) => !['WeComplete', 'WeClosed', 'WeCancelled'].includes(row.statusId)
// a milestone whose gate's approval was asked for and not decided (impl-projects.md P8b)
const milestoneIds = rows.filter((row) => row.workEffortTypeEnumId === 'WetMilestone').map((row) => row.workEffortId)
const awaitingIds = new Set()
for (let i = 0; i < milestoneIds.length; i += 500) for (const row of ec.entity.find('mantle.work.effort.WorkEffortApproval').condition('workEffortId', 'in', milestoneIds.slice(i, i + 500))
        .condition('statusId', 'WeaRequested').disableAuthz().list()) awaitingIds.add(row.workEffortId)
const inList = {upcoming: open, overdue: (row) => open(row) && row.estimatedCompletionDate != null && ec.l10n.format(String(toMillis(row.estimatedCompletionDate)), 'yyyy-MM-dd') < today,
    awaiting: (row) => awaitingIds.has(row.workEffortId),
    completed: (row) => ['WeComplete', 'WeClosed'].includes(row.statusId), all: () => true}
const ofKind = (row) => !kinds[kind] || kinds[kind].includes(row.workEffortTypeEnumId)
for (const key of lists) counts[key] = rows.filter((row) => ofKind(row) && inList[key](row)).length
for (const key of Object.keys(kinds)) kindCounts[key] = rows.filter((row) => inList[list](row) && (!kinds[key] || kinds[key].includes(row.workEffortTypeEnumId))).length
rows = rows.filter((row) => ofKind(row) && inList[list](row))
const names = {}
for (const row of Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', Array.from(new Set(rows.map((row) => row.rootWorkEffortId))).concat(['_NA_']))
        .selectField('workEffortId,workEffortName').list())) names[row.workEffortId] = row.workEffortName || row.workEffortId
const late = Number.MAX_SAFE_INTEGER
rows.sort((left, right) => String(names[left.rootWorkEffortId] || '').localeCompare(String(names[right.rootWorkEffortId] || ''))
        || String(left.rootWorkEffortId).localeCompare(String(right.rootWorkEffortId))
        || (list === 'completed' ? (toMillis(right.actualCompletionDate) || 0) - (toMillis(left.actualCompletionDate) || 0)
            : (toMillis(left.estimatedCompletionDate) ?? late) - (toMillis(right.estimatedCompletionDate) ?? late))
        || String(left.workEffortName || '').localeCompare(String(right.workEffortName || '')))
rowList = Array.from(ec.service.sync().name('ironstone.projects.PlanningServices.decorate#PlanItemRows').parameters({planList: rows.slice(0, 500), visibleInfo: vis}).call()?.rowList || [])

const L = (text) => ec.l10n.localize(text)
const parseDay = (text, label) => {
    const value = text == null ? '' : String(text).trim()
    if (!value) return null
    const parsed = /^\d{4}-\d{2}-\d{2}/.test(value) ? ec.l10n.parseTimestamp(value.substring(0, 10) + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS') : null
    if (parsed == null) ec.message.addError(ec.resource.expand('${label}: not a date (${value}); use yyyy-MM-dd', '', {label: L(label), value}))
    return parsed
}
const start = parseDay(startDay, 'Start')
const due = parseDay(dueDay, 'Due')
if (ec.message.hasError()) return
if (workEffortId) {
    const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#PlanItemAccess').parameters({workEffortId: workEffortId, need: 'update'}).call() || {}
    if (ec.message.hasError()) return
    const clear = []
    if (startDay != null && !String(startDay).trim()) clear.push('estimatedStartDate')
    if (dueDay != null && !String(dueDay).trim()) clear.push('estimatedCompletionDate')
    if (description != null && !String(description).trim()) clear.push('description')
    ec.service.sync().name('mantle.work.ProjectServices.update#Milestone').parameters({workEffortId: workEffortId, workEffortName: workEffortName ?? null,
        description: description != null && String(description).trim() ? description : null, estimatedStartDate: start, estimatedCompletionDate: due,
        statusId: statusId || null, clearFields: clear}).call()
    if (ec.message.hasError()) return
    message = ec.resource.expand('${name} saved', '', {name: workEffortName || access.plan.workEffortName || workEffortId})
    return
}
if (!rootWorkEffortId) { ec.message.addError(L('Choose the project')); return }
ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: rootWorkEffortId, need: 'update'}).call()
if (ec.message.hasError()) return
const release = kind === 'release'
workEffortId = ec.service.sync().name(release ? 'mantle.work.ProjectServices.create#Release' : 'mantle.work.ProjectServices.create#Milestone')
        .parameters({rootWorkEffortId: rootWorkEffortId, workEffortId: newWorkEffortId ? String(newWorkEffortId).trim() : null, workEffortName: workEffortName || '',
            description: description || null, estimatedStartDate: start, estimatedCompletionDate: due, statusId: statusId || 'WeInPlanning'}).call()?.workEffortId || null
if (ec.message.hasError()) return
message = ec.resource.expand(release ? 'Release ${name} made' : 'Milestone ${name} made', '', {name: workEffortName})

optionList = []
const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#PlanItemAccess').parameters({workEffortId: workEffortId, need: 'view'}).call() || {}
if (ec.message.hasError()) return
statusId = access.plan.statusId
const label = (id) => ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one()?.description || id
optionList.push({value: statusId, label: label(statusId)})
for (const move of Array.from(ec.entity.find('moqui.basic.StatusFlowTransition').condition({statusFlowId: 'Default', statusId: statusId}).useCache(true).list()))
    if (!optionList.some((option) => option.value === move.toStatusId)) optionList.push({value: move.toStatusId, label: label(move.toStatusId)})

const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#PlanItemAccess').parameters({workEffortId: workEffortId, need: 'update'}).call() || {}
if (ec.message.hasError()) return
const name = access.plan.workEffortName || workEffortId
if (field === 'due') {
    ec.service.sync().name('ironstone.projects.PlanningServices.save#PlanItem').parameters({workEffortId: workEffortId, dueDay: value == null ? '' : String(value)}).call()
    if (ec.message.hasError()) return
    const row = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
    valueText = row.estimatedCompletionDate != null ? ec.l10n.format(row.estimatedCompletionDate, 'MMM d, yyyy') : '—'
    message = ec.resource.expand('${name}: due ${valueText}', '', {name, valueText})
} else if (field === 'status') {
    if (!value) { ec.message.addError(ec.l10n.localize('Choose a status')); return }
    ec.service.sync().name('mantle.work.ProjectServices.update#Milestone').parameters({workEffortId: workEffortId, statusId: value}).call()
    if (ec.message.hasError()) return
    valueText = ec.entity.find('moqui.basic.StatusItem').condition('statusId', value).useCache(true).one()?.description || value
    message = ec.resource.expand('${name}: ${valueText}', '', {name, valueText})
} else {
    ec.message.addError(ec.resource.expand('${field} is not a field of the roadmap', '', {field}))
}

detail = null
const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#PlanItemAccess').parameters({workEffortId: workEffortId, need: 'view', kind: kind}).call() || {}
if (ec.message.hasError()) return
const L = (text) => ec.l10n.localize(text)
const plan = access.plan
const project = access.project
const isRelease = plan.workEffortTypeEnumId === 'WetRelease'
const decorated = Array.from(ec.service.sync().name('ironstone.projects.PlanningServices.decorate#PlanItemRows').parameters({planList: [plan]}).call()?.rowList || [])[0] || {}
const out = ec.service.sync().name('ironstone.projects.WorkItemServices.find#WorkItems').parameters({list: 'all', rootWorkEffortId: plan.rootWorkEffortId,
    milestoneId: isRelease ? null : workEffortId, releaseId: isRelease ? workEffortId : null, pageNoLimit: true, withCounts: false}).call() || {}
const stateOf = (statusId) => ['WeComplete', 'WeClosed'].includes(statusId) ? 'done' : statusId === 'WeCancelled' ? 'cancelled'
    : ['WeInPlanning', 'WeApproved'].includes(statusId) ? 'notStarted' : 'inProgress'
const groupOf = (purposeEnumId) => ['WepNewFeature', 'WepFeatureEnhance'].includes(purposeEnumId) ? 'features' : purposeEnumId === 'WepFix' ? 'fixes' : 'other'
const groupLabels = {features: L('Features'), fixes: L('Fixes'), other: L('Other')}
const groupOrder = {features: 0, fixes: 1, other: 2}
const rows = Array.from(out.rowList || []).map((row) => Object.assign(row, {state: stateOf(row.statusId), group: groupOf(row.purposeEnumId),
    groupLabel: groupLabels[groupOf(row.purposeEnumId)]}))
const keyNumber = (id) => { const match = /(\d+)$/.exec(String(id)); return match ? Number(match[1]) : 0 }
rows.sort((left, right) => (isRelease ? groupOrder[left.group] - groupOrder[right.group] : 0) || keyNumber(left.workEffortId) - keyNumber(right.workEffortId))
const toMillis = (value) => value == null || value === '' ? null : (typeof value === 'number' ? value : (/^-?\d+$/.test(String(value)) ? Number(String(value)) : Date.parse(String(value))))
const others = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', plan.rootWorkEffortId)
        .condition('workEffortTypeEnumId', plan.workEffortTypeEnumId).condition('statusId', 'in', ['WeInPlanning', 'WeApproved', 'WeInProgress', 'WeOnHold'])
        .condition('workEffortId', 'not-equals', workEffortId).list())
        .sort((left, right) => (toMillis(left.estimatedCompletionDate) ?? Number.MAX_SAFE_INTEGER) - (toMillis(right.estimatedCompletionDate) ?? Number.MAX_SAFE_INTEGER))
const moveIds = Array.from(ec.entity.find('moqui.basic.StatusFlowTransition').condition({statusFlowId: 'Default', statusId: plan.statusId}).useCache(true).list())
        .map((move) => move.toStatusId)
const settings = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: plan.rootWorkEffortId}).call()?.settings || {}
detail = Object.assign({}, decorated, {workEffortId: workEffortId, workEffortName: plan.workEffortName || workEffortId, description: plan.description || '',
    isRelease: isRelease, projectName: project.workEffortName || plan.rootWorkEffortId, canUpdate: !!access.canUpdate, canManage: !!access.canManage,
    stageStatusIds: ['WeInPlanning', 'WeInProgress', 'WeComplete', 'WeClosed'], moveIds: moveIds,
    rowList: rows, visibleCount: rows.length, estimateUnit: settings.WstEstimateUnit === 'points' ? 'points' : 'hours',
    docsSpaceId: settings.WstDocsWikiSpace || null,
    otherOptions: others.map((other) => ({key: other.workEffortId, text: (other.workEffortName || other.workEffortId)
        + (other.estimatedCompletionDate != null ? ' · ' + ec.l10n.format(other.estimatedCompletionDate, 'MMM d, yyyy') : '')}))})

optionList = []
const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#PlanItemAccess').parameters({workEffortId: workEffortId, need: 'update'}).call() || {}
if (ec.message.hasError()) { ec.message.clearErrors(); return }
const plan = access.plan
const assocType = plan.workEffortTypeEnumId === 'WetRelease' ? 'WeatRelease' : 'WeatMilestone'
const inIt = new Set(Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', workEffortId).condition('workEffortAssocTypeEnumId', assocType)
        .conditionDate('fromDate', 'thruDate', null).selectField('toWorkEffortId').list()).map((row) => row.toWorkEffortId))
const out = ec.service.sync().name('ironstone.projects.WorkItemServices.find#WorkItems').parameters({list: 'all', rootWorkEffortId: plan.rootWorkEffortId,
    text: term ? String(term).trim() : null, pageSize: 40, withCounts: false}).call() || {}
const rows = Array.from(out.rowList || []).filter((row) => !inIt.has(row.workEffortId))
rows.sort((left, right) => Number(!left.isOpen) - Number(!right.isOpen))
for (const row of rows.slice(0, 20)) optionList.push({value: row.workEffortId, label: row.workEffortId + ' ' + (row.workEffortName || '') + (row.isOpen ? '' : ' (' + (row.statusLabel || '') + ')')})

doneCount = 0; failedCount = 0
const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#PlanItemAccess').parameters({workEffortId: workEffortId, need: 'update'}).call() || {}
if (ec.message.hasError()) return
const plan = access.plan
const assocType = plan.workEffortTypeEnumId === 'WetRelease' ? 'WeatRelease' : 'WeatMilestone'
const ids = (workEffortIds == null ? [] : (typeof workEffortIds === 'string' ? workEffortIds.split(',') : Array.from(workEffortIds))).map((id) => String(id).trim()).filter((id) => id)
if (!ids.length) { ec.message.addError(ec.l10n.localize('Choose the work items')); return }
const failed = []
for (const id of ids) {
    ec.message.pushErrors()
    try {
        const item = ec.service.sync().name('ironstone.commons.TaskServices.get#TaskAccess').parameters({workEffortId: id, need: 'check', app: 'projects'}).call() || {}
        if (ec.message.hasError() || !item.visible) throw new Error(ec.resource.expand('${id} is not available', '', {id}))
        if (remove) {
            const current = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', workEffortId).condition('toWorkEffortId', id)
                    .condition('workEffortAssocTypeEnumId', assocType).conditionDate('fromDate', 'thruDate', null).list())
            for (const assoc of current) { assoc.set('thruDate', ec.user.nowTimestamp); assoc.update() }
        } else {
            ec.service.sync().name('mantle.work.TaskServices.set#TaskPlanItem').parameters({workEffortId: id, assocTypeEnumId: assocType, planWorkEffortId: workEffortId}).call()
        }
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        doneCount++
    } catch (err) {
        failedCount++
        failed.push(id)
        ec.logger.warn(`${remove ? 'Remove from' : 'Add to'} ${workEffortId}: ${id} not done: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
const name = plan.workEffortName || workEffortId
message = ec.resource.expand(remove ? '${count} taken out of ${name}' : '${count} added to ${name}', '', {count: doneCount, name})
        + (failedCount ? ec.resource.expand('; not done: ${ids}', '', {ids: failed.join(', ')}) : '')
if (!doneCount) { ec.message.addError(message); message = null }

movedCount = 0
const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#PlanItemAccess').parameters({workEffortId: workEffortId, need: 'update'}).call() || {}
if (ec.message.hasError()) return
const plan = access.plan
const assocType = plan.workEffortTypeEnumId === 'WetRelease' ? 'WeatRelease' : 'WeatMilestone'
if (toWorkEffortId) {
    const target = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', toWorkEffortId).one()
    if (target == null || target.workEffortTypeEnumId !== plan.workEffortTypeEnumId || target.rootWorkEffortId !== plan.rootWorkEffortId || toWorkEffortId === workEffortId
            || ['WeComplete', 'WeClosed', 'WeCancelled'].includes(target.statusId)) {
        ec.message.addError(ec.resource.expand('${toWorkEffortId} is not another open one of the project', '', {toWorkEffortId})); return
    }
}
const ids = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', workEffortId).condition('workEffortAssocTypeEnumId', assocType)
        .conditionDate('fromDate', 'thruDate', null).list()).map((row) => row.toWorkEffortId)
const open = ids.length ? Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', ids)
        .condition('statusId', 'not-in', ['WeComplete', 'WeClosed', 'WeCancelled']).list()) : []
for (const item of open) {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('mantle.work.TaskServices.set#TaskPlanItem').parameters({workEffortId: item.workEffortId, assocTypeEnumId: assocType,
            planWorkEffortId: toWorkEffortId || null}).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        movedCount++
    } catch (err) {
        ec.logger.warn(`Move unfinished of ${workEffortId}: ${item.workEffortId} not moved: ${err && err.message ? err.message : err}`)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
const to = toWorkEffortId ? (ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', toWorkEffortId).one()?.workEffortName || toWorkEffortId) : null
message = to ? ec.resource.expand('${count} unfinished moved to ${to}', '', {count: movedCount, to}) : ec.resource.expand('${count} unfinished taken out', '', {count: movedCount})

code = {hosting: false, mergeRequestList: [], tagList: [], repositoryOptions: [], tagOptions: [], failedParts: []}
const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#PlanItemAccess').parameters({workEffortId: workEffortId, need: 'view', kind: 'release'}).call() || {}
if (ec.message.hasError()) return
code.hosting = !!ec.service.sync().name('ironstone.projects.CodeServices.get#CodeHosting').call()?.available
if (!code.hosting) return
const plan = access.plan
const L = (text) => ec.l10n.localize(text)
const labels = ec.service.sync().name('ironstone.projects.CodeServices.get#MergeRequestLabels').call()?.labels || {}
const fmt = (value) => value ? ec.l10n.format(value, 'MMM d, yyyy') : ''
const part = (name, run) => {
    ec.message.pushErrors()
    try { run(); if (ec.message.hasError()) throw new Error(ec.message.getErrorsString()) }
    catch (err) { code.failedParts.push(name); ec.logger.warn(`Release ${workEffortId}: ${name} not read: ${err && err.message ? err.message : err}`) }
    finally { ec.message.clearErrors(); ec.message.popErrors() }
}
const viewable = {}
const accessOf = (repositoryId) => {
    if (!(repositoryId in viewable)) {
        ec.message.pushErrors()
        try {
            const repoAccess = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess').parameters({repositoryId}).call() || {}
            viewable[repositoryId] = ec.message.hasError() || !repoAccess.canView ? null : repoAccess
        } catch (err) { viewable[repositoryId] = null }
        finally { ec.message.clearErrors(); ec.message.popErrors() }
    }
    return viewable[repositoryId]
}
const linked = Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRepository').condition('workEffortId', plan.rootWorkEffortId)
        .conditionDate('fromDate', 'thruDate', null).orderBy('repositoryId').list()).map((row) => row.repositoryId)
part('the merge requests', () => {
    const itemIds = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortId', workEffortId).condition('workEffortAssocTypeEnumId', 'WeatRelease')
            .conditionDate('fromDate', 'thruDate', null).list()).map((row) => row.toWorkEffortId)
    // only the items the user sees are named (a client: those shared with it; ironstone.projects.CodeServices.get#VisibleWorkEfforts)
    const seenItems = itemIds.length ? (ec.service.sync().name('ironstone.projects.CodeServices.get#VisibleWorkEfforts').parameters({workEffortIdList: itemIds})
            .call()?.effortMap || {}) : {}
    const links = itemIds.length ? Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitMergeRequest').condition('workEffortId', 'in', itemIds).disableAuthz().list())
            .filter((link) => seenItems[link.workEffortId]) : []
    const mrIds = Array.from(new Set(links.map((link) => link.mergeRequestId)))
    const mrs = mrIds.length ? Array.from(ec.entity.find('moqui.resource.GitMergeRequest').condition('mergeRequestId', 'in', mrIds).disableAuthz().list()) : []
    const order = {GmrMerged: 0, GmrOpen: 1, GmrDraft: 2, GmrClosed: 3}
    for (const mr of mrs) {
        if (!accessOf(mr.repositoryId)) continue
        const status = (labels.status || {})[mr.statusId] || [mr.statusId, 'grey-8', 'sym_o_merge']
        code.mergeRequestList.push({mergeRequestId: mr.mergeRequestId, repositoryId: mr.repositoryId, numText: '!' + mr.mergeRequestNum, title: mr.title || '',
            statusId: mr.statusId, statusLabel: status[0], statusColor: status[1], statusIcon: status[2], mergedText: fmt(mr.mergedDate),
            itemsText: links.filter((link) => link.mergeRequestId === mr.mergeRequestId).map((link) => link.workEffortId).sort().join(', '),
            url: '/qapps/Projects/Code/MergeRequestDetail?mergeRequestId=' + encodeURIComponent(mr.mergeRequestId),
            sortKey: (order[mr.statusId] ?? 9) * 1e9 + Number(mr.mergeRequestNum || 0)})
    }
    code.mergeRequestList.sort((left, right) => left.sortKey - right.sortKey || String(left.repositoryId).localeCompare(String(right.repositoryId)))
})
part('the tags', () => {
    for (const link of Array.from(ec.entity.find('mantle.work.effort.WorkEffortGitRef').condition('workEffortId', workEffortId).condition('refType', 'tag')
            .orderBy('-linkedDate').list())) {
        if (!accessOf(link.repositoryId)) continue
        const source = link.linkSourceEnumId ? ec.entity.find('moqui.basic.Enumeration').condition('enumId', link.linkSourceEnumId).useCache(true).one()?.description || '' : ''
        code.tagList.push({repositoryId: link.repositoryId, refName: link.refName, tagName: String(link.refName).replace(/^refs\/tags\//, ''),
            commitShort: link.objectId ? String(link.objectId).substring(0, 8) : '', commitId: link.objectId || '', ended: link.thruDate != null,
            sourceText: source, linkedText: fmt(link.linkedDate),
            commitUrl: link.objectId ? '/qapps/Projects/Code/CommitDetail?repositoryId=' + encodeURIComponent(link.repositoryId) + '&commitId=' + encodeURIComponent(link.objectId) : '',
            repositoryUrl: '/qapps/Projects/Code/RepositoryDetail/Tags?repositoryId=' + encodeURIComponent(link.repositoryId)})
    }
})
part('the repositories', () => {
    const tagged = new Set(code.tagList.map((tag) => tag.repositoryId + '|' + tag.refName))
    for (const repositoryId of linked) {
        const repoAccess = accessOf(repositoryId)
        if (!repoAccess) continue
        const refs = ec.service.sync().name('org.moqui.git.GitServices.get#GitRefs').parameters({repositoryId}).call() || {}
        if (ec.message.hasError()) { ec.message.clearErrors(); continue }
        if ((repoAccess.canCreate || repoAccess.canUpdate) && !repoAccess.archived)
            code.repositoryOptions.push({key: repositoryId, text: repositoryId + ' · ' + (refs.defaultBranch || 'main'), defaultBranch: refs.defaultBranch || 'main'})
        for (const ref of Array.from(refs.refList || [])) {
            if (!String(ref.refName).startsWith('refs/tags/') || tagged.has(repositoryId + '|' + ref.refName)) continue
            code.tagOptions.push({key: repositoryId + '|' + ref.refName, text: repositoryId + ' · ' + String(ref.refName).replace(/^refs\/tags\//, '')})
        }
    }
})
const version = String(plan.workEffortName || '')
code.defaultTagName = /^\d/.test(version) ? 'v' + version : version

const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#PlanItemAccess').parameters({workEffortId: workEffortId, need: 'update', kind: 'release'}).call() || {}
if (ec.message.hasError()) return
const plan = access.plan
const linked = ec.entity.find('mantle.work.effort.WorkEffortGitRepository').condition({workEffortId: plan.rootWorkEffortId, repositoryId: repositoryId})
        .conditionDate('fromDate', 'thruDate', null).count() > 0
if (!linked) { ec.message.addError(ec.resource.expand('${repositoryId} is not a repository of the project', '', {repositoryId})); return }
const version = String(plan.workEffortName || workEffortId)
const name = String(tagName || '').trim() || (/^\d/.test(version) ? 'v' + version : version)
const out = ec.service.sync().name('org.moqui.git.GitServices.create#GitRef').parameters({repositoryId: repositoryId, refName: name, refType: 'tag',
    revision: revision ? String(revision).trim() : null, message: ec.resource.expand('Release ${version}', '', {version})}).call() || {}
if (ec.message.hasError()) return
const refName = String(out.refName || name).startsWith('refs/') ? String(out.refName || name) : 'refs/tags/' + (out.refName || name)
ec.service.sync().name('mantle.work.GitServices.store#WorkEffortRef').parameters({workEffortId: workEffortId, repositoryId: repositoryId, refName: refName,
    objectId: out.commitId || out.objectId || null, linkSourceEnumId: 'WglsExplicit'}).call()
if (ec.message.hasError()) return
message = ec.resource.expand('Tag ${name} made in ${repositoryId}', '', {name, repositoryId})

notes = null
const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#PlanItemAccess').parameters({workEffortId: workEffortId, need: 'view', kind: 'release'}).call() || {}
if (ec.message.hasError()) return
const kept = ec.service.sync().name('mantle.work.ProjectServices.get#ReleaseNotes').parameters({workEffortId: workEffortId}).call() || {}
// a client contact (impl-projects.md P10b) reads the notes once published, never a draft or a generated one (which names
// every item of the release, the team's own too), and no page link (the docs space is not its)
if (ec.user.userId && ec.user.hasPermission('PROJECT_CLIENT')) {
    const published = !!kept.wikiPageId && !!String(kept.notesText || '').trim()
    notes = {notesText: published ? kept.notesText : '', draft: false, savedText: '', published: published, pagePath: '', pageUrl: '',
        docsSpaceId: null, openCount: 0, clientHidden: !published}
    return
}
const draft = !String(kept.notesText || '').trim()
const generated = draft ? ec.service.sync().name('mantle.work.ProjectServices.generate#ReleaseNotes').parameters({workEffortId: workEffortId}).call() || {} : {}
const settings = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: access.plan.rootWorkEffortId}).call()?.settings || {}
let pageUrl = ''
if (kept.wikiPageId) {
    const pageAccess = ec.service.sync().name('org.moqui.resource.WikiServices.get#WikiPageAccess').parameters({wikiPageId: kept.wikiPageId}).call() || {}
    if (!ec.message.hasError() && pageAccess.canView) pageUrl = settings.WstDocsWikiSpace === kept.wikiSpaceId
        ? '/qapps/Projects/Projects/ProjectDetail/Docs?workEffortId=' + encodeURIComponent(access.plan.rootWorkEffortId) + '&wikiSpaceId=' + encodeURIComponent(kept.wikiSpaceId)
            + '&pagePath=' + encodeURIComponent(kept.pagePath || '')
        : '/qapps/Commons/Knowledge?wikiPageId=' + encodeURIComponent(kept.wikiPageId)
    ec.message.clearErrors()
}
notes = {notesText: draft ? (generated.notesText || '') : kept.notesText, draft: draft, savedText: kept.contentDate ? ec.l10n.format(kept.contentDate, 'MMM d, yyyy h:mm a') : '',
    published: !!kept.wikiPageId, pagePath: kept.pagePath || '', pageUrl: pageUrl, docsSpaceId: settings.WstDocsWikiSpace || null,
    openCount: generated.openCount || 0}

messageType = 'success'
const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#PlanItemAccess').parameters({workEffortId: workEffortId, need: 'update', kind: 'release'}).call() || {}
if (ec.message.hasError()) return
const L = (text) => ec.l10n.localize(text)
const version = access.plan.workEffortName || workEffortId
if (generate) {
    const out = ec.service.sync().name('mantle.work.ProjectServices.generate#ReleaseNotes').parameters({workEffortId: workEffortId}).call() || {}
    if (ec.message.hasError()) return
    ec.service.sync().name('mantle.work.ProjectServices.store#ReleaseNotes').parameters({workEffortId: workEffortId, notesText: out.notesText}).call()
    if (ec.message.hasError()) return
    message = ec.resource.expand('A draft of the notes of ${version}: ${count} done work items', '', {version, count: out.itemCount || 0})
    return
}
if (!publish) {
    ec.service.sync().name('mantle.work.ProjectServices.store#ReleaseNotes').parameters({workEffortId: workEffortId, notesText: notesText || ''}).call()
    if (ec.message.hasError()) return
    message = ec.resource.expand('The notes of ${version} saved', '', {version})
    return
}
if (!toDocs && !toChangelog && !notify) { ec.message.addError(L('Choose where to publish the notes')); return }
const out = ec.service.sync().name('mantle.work.ProjectServices.publish#ReleaseNotes').parameters({workEffortId: workEffortId, notesText: notesText || null,
    toDocs: toDocs, toChangelog: toChangelog, repositoryId: repositoryId || null, notify: notify}).call() || {}
if (ec.message.hasError()) return
const names = {docs: L('the docs space'), 'CHANGELOG.md': 'CHANGELOG.md', followers: L('the followers')}
const done = Array.from(out.publishedList || []).map((name) => names[name] || name)
if (!done.length) { ec.message.addError(ec.resource.expand('The notes of ${version} were not published', '', {version})); return }
message = ec.resource.expand('The notes of ${version} published to ${where}', '', {version, where: done.join(', ')})
if (Array.from(out.failedList || []).length) messageType = 'warning'

const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#PlanItemAccess').parameters({workEffortId: workEffortId, need: 'update', kind: 'release'}).call() || {}
if (ec.message.hasError()) return
const L = (text) => ec.l10n.localize(text)
const out = ec.service.sync().name('mantle.work.ProjectServices.release#Release').parameters({workEffortId: workEffortId, moveUnfinishedTo: moveUnfinishedTo || 'next',
    createTag: createTag, repositoryId: repositoryId || null, tagName: tagName || null, revision: revision || null, publish: publish,
    toChangelog: toChangelog, notify: notify}).call() || {}
if (ec.message.hasError()) return
const version = access.plan.workEffortName || workEffortId
const parts = [ec.resource.expand('${version} released', '', {version})]
if (out.movedCount) {
    const to = out.movedToWorkEffortId ? (ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', out.movedToWorkEffortId).one()?.workEffortName
            || out.movedToWorkEffortId) : null
    parts.push(to ? ec.resource.expand('${count} not done moved to ${to}', '', {count: out.movedCount, to}) : ec.resource.expand('${count} not done taken out', '', {count: out.movedCount}))
}
if (out.tagRefName) parts.push(ec.resource.expand('tag ${tag}', '', {tag: String(out.tagRefName).replace(/^refs\/tags\//, '')}))
if (Array.from(out.publishedList || []).length) parts.push(ec.resource.expand('notes published to ${where}', '', {where: Array.from(out.publishedList).join(', ')}))
message = parts.join(', ')

const L = (text) => ec.l10n.localize(text)
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const dayOf = (value) => toMillis(value) == null ? null : ec.l10n.format(String(toMillis(value)), 'yyyy-MM-dd')
const todayText = dayOf(ec.user.nowTimestamp)
const theMode = ['items', 'plan', 'portfolio'].includes(mode) ? mode : 'items'
timeline = {mode: theMode, todayText: todayText, rowList: [], dependencyList: [], planItemList: [], holidayList: [], filters: {}, project: null, truncated: false}
let project = null
let access = {}
if (rootWorkEffortId) {
    access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: rootWorkEffortId, need: 'none'}).call() || {}
    if (!access.canView) { timeline.notAvailable = true; return }
    project = access.project
    timeline.project = {workEffortId: rootWorkEffortId, workEffortName: project.workEffortName || rootWorkEffortId, canUpdate: !!access.canUpdate,
        canManage: !!access.canManage, startDay: dayOf(project.estimatedStartDate), dueDay: dayOf(project.estimatedCompletionDate)}
}
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
const members = new Set(Array.from(vis.memberProjectIds || []))
const managed = new Set(Array.from(vis.managedProjectIds || []))
const projectsManager = ec.user.isInGroup('BOSS_PROJECT_MANAGER') || ec.user.isInGroup('ADMIN')
const mayUpdate = (projectId) => !!vis.allProjects || projectsManager || members.has(projectId) || managed.has(projectId)
// the holidays of the organizations of the projects drawn (WepHoliday days), a year back and two ahead
const holidays = (projectIds) => {
    const owners = Array.from(new Set(Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', projectIds.concat(['_NA_']))
            .selectField('workEffortId,ownerPartyId').list()).map((row) => row.ownerPartyId).filter((id) => id)))
    if (!owners.length) return []
    const from = ec.l10n.parseDate(String(Number(todayText.substring(0, 4)) - 1) + todayText.substring(4), 'yyyy-MM-dd')
    const thru = ec.l10n.parseDate(String(Number(todayText.substring(0, 4)) + 2) + todayText.substring(4), 'yyyy-MM-dd')
    return Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('purposeEnumId', 'WepHoliday').condition('ownerPartyId', 'in', owners)
            .condition('allDayStart', 'greater-equals', from).condition('allDayStart', 'less-equals', thru).selectField('allDayStart,workEffortName').list())
            // a date field reaches a script as the epoch millis of its UTC midnight (impl-projects.md F79)
            .map((row) => ({day: new Date(toMillis(row.allDayStart)).toISOString().slice(0, 10), name: row.workEffortName || L('Holiday')}))
}

if (theMode === 'plan') {
    const out = ec.service.sync().name('ironstone.projects.PlanningServices.find#RoadmapItems').parameters({list: planList || 'all', kind: 'all',
        rootWorkEffortId: rootWorkEffortId || null, text: text || null}).call() || {}
    timeline.rowList = Array.from(out.rowList || []).map((row) => Object.assign({}, row, {rowKind: row.kind, depth: 0, childCount: 0,
        progress: row.percentDone || 0, canMove: !!row.canUpdate && row.isOpen}))
    timeline.holidayList = holidays(Array.from(new Set(timeline.rowList.map((row) => row.rootWorkEffortId))))
    timeline.filters.planList = out.list || 'all'
    return
}
if (theMode === 'portfolio') {
    const out = ec.service.sync().name('ironstone.projects.ProjectServices.find#Projects').parameters({list: projectList || 'active', text: text || null,
        pageNoLimit: true, withCounts: false}).call() || {}
    const projects = Array.from(out.rowList || []).slice(0, 300)
    const ids = projects.map((row) => row.workEffortId)
    // a project without dates spans its items
    const spans = {}
    if (ids.length) for (const row of ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js').without(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', 'in', ids).condition('workEffortTypeEnumId', 'WetTask'), vis)
            .condition('statusId', 'not-equals', 'WeCancelled').selectField('rootWorkEffortId,estimatedStartDate,estimatedCompletionDate').list()) {
        const span = spans[row.rootWorkEffortId] || (spans[row.rootWorkEffortId] = [null, null])
        const start = dayOf(row.estimatedStartDate) || dayOf(row.estimatedCompletionDate)
        const due = dayOf(row.estimatedCompletionDate) || start
        if (start && (!span[0] || start < span[0])) span[0] = start
        if (due && (!span[1] || due > span[1])) span[1] = due
    }
    const plans = ids.length ? Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', 'in', ids)
            .condition('workEffortTypeEnumId', 'in', ['WetMilestone', 'WetRelease']).condition('statusId', 'not-equals', 'WeCancelled').list()) : []
    timeline.planItemList = plans.length ? Array.from(ec.service.sync().name('ironstone.projects.PlanningServices.decorate#PlanItemRows').parameters({planList: plans,
        visibleInfo: vis}).call()?.rowList || []) : []
    timeline.rowList = projects.map((row) => {
        const span = spans[row.workEffortId] || [null, null]
        return {workEffortId: row.workEffortId, workEffortName: row.workEffortName, url: row.url, rowKind: 'project', depth: row.isSubProject ? 1 : 0, childCount: 0,
            statusId: row.statusId, statusLabel: row.statusLabel, statusColor: row.statusColor, healthLabel: row.healthLabel, healthColor: row.healthColor,
            assigneeText: row.managerName || '', startDay: dayOf(row.estimatedStartDate) || span[0], dueDay: dayOf(row.estimatedCompletionDate) || span[1],
            datesFromItems: !row.estimatedStartDate && !row.estimatedCompletionDate && !!(span[0] || span[1]),
            progress: row.percentDone || 0, rootWorkEffortId: row.workEffortId, canMove: false}
    })
    timeline.holidayList = holidays(ids)
    timeline.filters.projectList = projectList || 'active'
    return
}

// ===== items: the find, its ancestors, the dependencies and the plan
const found = Array.from(ec.service.sync().name('ironstone.projects.WorkItemServices.find#WorkItems').parameters({list: list || 'all', rootWorkEffortId: rootWorkEffortId || null,
    text: text || null, purposeEnumId: purposeEnumId || null, assigneePartyId: assigneePartyId || null, sprintId: sprintId || null,
    milestoneId: milestoneId || null, releaseId: releaseId || null, labelId: labelId || null, treeOrder: true, pageNoLimit: true, withCounts: false}).call()?.rowList || [])
        .filter((row) => row.statusId !== 'WeCancelled')
if (found.length > 500) timeline.truncated = true
const ids = found.slice(0, 500).map((row) => row.workEffortId)
const data = ec.service.sync().name('mantle.work.ProjectServices.get#TimelineData').parameters({workEffortIds: ids, withAncestors: true,
    rootWorkEffortId: rootWorkEffortId || null}).call() || {}
const items = Array.from(data.itemList || [])
const decorated = {}
if (items.length) for (const row of Array.from(ec.service.sync().name('ironstone.projects.WorkItemServices.decorate#WorkItemRows').parameters({taskList: items,
        visibleInfo: vis}).call()?.rowList || [])) decorated[row.workEffortId] = row
timeline.rowList = items.map((item) => {
    const row = decorated[item.workEffortId] || {}
    return {workEffortId: item.workEffortId, workEffortName: item.workEffortName || item.workEffortId, url: row.url, rowKind: 'item',
        typeIcon: row.typeIcon || 'sym_o_task_alt', purposeLabel: row.purposeLabel || '', statusId: item.statusId, statusLabel: row.statusLabel || '',
        statusColor: row.statusColor || 'grey-7', isDone: !!item.isDone, assigneePartyId: row.assigneePartyId || null, assigneeText: row.assigneeText || '',
        parentWorkEffortId: item.parentWorkEffortId || null, rootWorkEffortId: item.rootWorkEffortId || null, projectName: row.projectName || '',
        depth: item.depth || 0, childCount: item.childCount || 0, ancestor: !!item.ancestor, sequenceNum: item.sequenceNum ?? null,
        startDay: item.startDay, dueDay: item.dueDay,
        spanStartDay: item.spanStartDay, spanDueDay: item.spanDueDay, progress: item.progress || 0,
        milestoneId: item.milestoneId, milestoneName: row.milestoneName || '', sprintId: item.sprintId, sprintName: row.sprintName || '',
        releaseId: item.releaseId, releaseName: row.releaseName || '', canMove: mayUpdate(item.rootWorkEffortId) && item.statusId !== 'WeCancelled'}
})
timeline.dependencyList = Array.from(data.dependencyList || []).map((link) => ({workEffortId: link.workEffortId, toWorkEffortId: link.toWorkEffortId,
    lagDays: link.lagDays, violated: !!link.violated, canChange: mayUpdate((items.find((item) => item.workEffortId === link.workEffortId) || {}).rootWorkEffortId)}))
const planIds = Array.from(data.planItemList || []).map((plan) => plan.workEffortId)
const planRows = planIds.length ? Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', planIds).list()) : []
const plans = planRows.length ? Array.from(ec.service.sync().name('ironstone.projects.PlanningServices.decorate#PlanItemRows').parameters({planList: planRows,
    visibleInfo: vis}).call()?.rowList || []) : []
const order = new Map(planIds.map((id, index) => [id, index]))
timeline.planItemList = plans.sort((left, right) => order.get(left.workEffortId) - order.get(right.workEffortId))
        .map((plan) => Object.assign({}, plan, {canMove: plan.kind !== 'sprint' && !!plan.canUpdate && plan.isOpen}))
const projectIds = Array.from(new Set(items.map((item) => item.rootWorkEffortId).filter((id) => id).concat(rootWorkEffortId ? [rootWorkEffortId] : [])))
timeline.holidayList = holidays(projectIds)
// the find's options, in one project
if (rootWorkEffortId) {
    const assignees = {}
    const types = {}
    for (const row of timeline.rowList) {
        if (row.assigneePartyId) assignees[row.assigneePartyId] = String(row.assigneeText || '').split(', ')[0] || row.assigneePartyId
        if (row.purposeLabel) types[row.purposeLabel] = true
    }
    timeline.filters = {assigneeOptions: Object.keys(assignees).map((key) => ({value: key, label: assignees[key]})).sort((a, b) => a.label.localeCompare(b.label)),
        typeOptions: Array.from(ec.service.sync().name('ironstone.projects.ProjectServices.get#WorkItemTypes').parameters({rootWorkEffortId: rootWorkEffortId}).call()?.offeredList || [])
            .map((type) => ({value: type.enumId, label: type.label})),
        sprintOptions: timeline.planItemList.filter((plan) => plan.kind === 'sprint').map((plan) => ({value: plan.workEffortId, label: plan.workEffortName})),
        milestoneOptions: timeline.planItemList.filter((plan) => plan.kind === 'milestone').map((plan) => ({value: plan.workEffortId, label: plan.workEffortName})),
        releaseOptions: timeline.planItemList.filter((plan) => plan.kind === 'release').map((plan) => ({value: plan.workEffortId, label: plan.workEffortName}))}
}

const L = (text, values) => ec.resource.expand(ec.l10n.localize(text), '', values || {})
const record = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (record == null) { ec.message.addError(L('${id} is not available', {id: workEffortId})); return }
if (record.workEffortTypeEnumId === 'WetTask') {
    ec.service.sync().name('ironstone.commons.TaskServices.get#TaskAccess').parameters({workEffortId: workEffortId, need: 'update', app: 'projects'}).call()
} else if (['WetMilestone', 'WetRelease'].includes(record.workEffortTypeEnumId)) {
    ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: record.rootWorkEffortId || '', need: 'update'}).call()
} else { ec.message.addError(L('${id} is not moved on the timeline', {id: workEffortId})); return }
if (ec.message.hasError()) return
const out = ec.service.sync().name('mantle.work.TaskServices.set#TaskDates').parameters({workEffortId: workEffortId, startDay: startDay,
    dueDay: dueDay, shiftDays: shiftDays, moveSubtree: !!moveSubtree && record.workEffortTypeEnumId === 'WetTask', autoSchedule: !!autoSchedule}).call() || {}
if (ec.message.hasError()) return
movedList = Array.from(out.movedList || [])
const failed = Array.from(out.failedList || [])
const others = movedList.filter((row) => row.workEffortId !== workEffortId).map((row) => row.workEffortId)
message = others.length ? L('${id} moved, and ${others}', {id: workEffortId, others: others.join(', ')}) : L('${id} moved', {id: workEffortId})
if (failed.length) message += '; ' + L('not moved: ${ids}', {ids: failed.map((row) => row.workEffortId + ' (' + row.error + ')').join(', ')})

const L = (text, values) => ec.resource.expand(ec.l10n.localize(text), '', values || {})
ec.service.sync().name('ironstone.commons.TaskServices.get#TaskAccess').parameters({workEffortId: workEffortId, need: 'update', app: 'projects'}).call()
if (ec.message.hasError()) return
ec.service.sync().name('ironstone.commons.TaskServices.get#TaskAccess').parameters({workEffortId: toWorkEffortId, need: 'view', app: 'projects'}).call()
if (ec.message.hasError()) return
const lagText = lagDays == null ? '' : String(lagDays).trim()
const lag = lagText === '' ? null : Number(lagText)
if (lagText !== '' && !Number.isFinite(lag)) { ec.message.addError(L('The lag is a number of working days')); return }
const out = ec.service.sync().name('mantle.work.TaskServices.add#TaskDependency').parameters({workEffortId: workEffortId, toWorkEffortId: toWorkEffortId,
    lagDays: lag}).call() || {}
if (ec.message.hasError()) return
message = out.created ? L('${id} now waits for ${to}', {id: workEffortId, to: toWorkEffortId}) : L('The lag of ${id} after ${to} changed', {id: workEffortId, to: toWorkEffortId})

eventList = []
failedSources = []
const access = ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: rootWorkEffortId, need: 'view'}).call() || {}
if (ec.message.hasError()) return
const dayOk = (text) => /^\d{4}-\d{2}-\d{2}$/.test(String(text || ''))
if (!dayOk(start) || !dayOk(end) || String(end) < String(start)) { ec.message.addError(ec.l10n.localize('The range is two days, yyyy-MM-dd')); return }
const L = (text) => ec.l10n.localize(text)
const addDays = (text, days) => { const d = new Date(text + 'T12:00:00Z'); d.setUTCDate(d.getUTCDate() + days); return d.toISOString().substring(0, 10) }
const wall = (text) => text ? String(text).replace('T', ' ').substring(0, 16) : null
const attempt = (name, run) => {
    ec.message.pushErrors()
    try { run(); if (ec.message.hasError()) throw new Error(ec.message.getErrorsString()) }
    catch (err) { failedSources.push(name); ec.logger.error(`Project calendar ${name} of ${rootWorkEffortId} for ${ec.user.username} not read: ${err && err.message ? err.message : err}`) }
    finally { ec.message.clearErrors(); ec.message.popErrors() }
}
attempt('events', () => {
    const out = ec.service.sync().name('mantle.work.EventServices.get#FullCalendarData').parameters({rootWorkEffortId: rootWorkEffortId, start: start,
        end: end, excludeCancelled: true, titleGString: '${workEffort.workEffortName || "(no title)"}'}).call()
    if (ec.message.hasError()) return
    const partyId = ec.user.userAccount?.partyId || null
    for (const event of Array.from(out?.eventList || [])) {
        const instanceStart = event.instanceStart ? (event.allDay ? String(event.instanceStart).substring(0, 10) : wall(event.instanceStart)) : null
        eventList.push({kind: 'event', key: event.workEffortId + '|' + (instanceStart || '') + '|' + event.startMillis, workEffortId: event.workEffortId,
            title: event.title, start: event.allDay ? event.start : wall(event.start), end: event.allDay ? event.end : wall(event.end), allDay: !!event.allDay,
            color: null, statusId: event.statusId || null, partyStatusId: event.partyStatusId || null, recurring: !!event.recurring,
            recurringEventId: event.recurringEventId || null, instanceStart: instanceStart, freeBusyOnly: !!event.freeBusyOnly,
            location: event.location || null, canEdit: !!partyId && event.ownerPartyId === partyId, isOrganizer: !!partyId && event.ownerPartyId === partyId,
            hasAttendees: false, url: '/qapps/Commons/Calendar/EventDetail?workEffortId=' + encodeURIComponent(event.workEffortId)})
    }
})
attempt('plan', () => {
    const rows = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition('rootWorkEffortId', rootWorkEffortId)
            .condition('workEffortTypeEnumId', 'in', ['WetMilestone', 'WetRelease', 'WetSprint']).condition('statusId', 'not-equals', 'WeCancelled').list())
    const plans = rows.length ? Array.from(ec.service.sync().name('ironstone.projects.PlanningServices.decorate#PlanItemRows').parameters({planList: rows}).call()?.rowList || []) : []
    for (const plan of plans) {
        const first = plan.startDay || plan.dueDay
        const last = plan.dueDay || plan.startDay
        if (!first || last < start || first > end) continue
        // a sprint over its days; a milestone or release on its due day (over its days it would fill every day of a month), and a
        // phase's start as a day of its own
        if (plan.kind === 'sprint') {
            eventList.push({kind: 'sprint', key: 'sprint|' + plan.workEffortId, workEffortId: plan.workEffortId, title: plan.workEffortName,
                start: first, end: addDays(last, 1), allDay: true, statusId: plan.statusId, done: !plan.isOpen, canEdit: false, url: plan.url})
            continue
        }
        if (plan.dueDay && plan.dueDay >= start && plan.dueDay <= end) eventList.push({kind: plan.kind, key: plan.kind + '|' + plan.workEffortId,
            workEffortId: plan.workEffortId, title: plan.workEffortName + ' · ' + plan.kindLabel, start: plan.dueDay, end: addDays(plan.dueDay, 1), allDay: true,
            statusId: plan.statusId, done: !plan.isOpen, canEdit: !!plan.canUpdate && plan.isOpen, movable: true, url: plan.url})
        if (plan.startDay && plan.startDay !== plan.dueDay && plan.startDay >= start && plan.startDay <= end) eventList.push({kind: plan.kind,
            key: plan.kind + '|start|' + plan.workEffortId, workEffortId: plan.workEffortId, title: plan.workEffortName + ' · ' + L('starts'),
            start: plan.startDay, end: addDays(plan.startDay, 1), allDay: true, statusId: plan.statusId, done: !plan.isOpen, canEdit: false, url: plan.url})
    }
})
attempt('work items', () => {
    const pattern = 'yyyy-MM-dd HH:mm:ss.SSS'
    const out = ec.service.sync().name('ironstone.projects.WorkItemServices.find#WorkItems').parameters({list: 'all', rootWorkEffortId: rootWorkEffortId,
        dueFrom: ec.l10n.parseTimestamp(start + ' 00:00:00.000', pattern), dueThru: ec.l10n.parseTimestamp(addDays(end, 1) + ' 00:00:00.000', pattern),
        pageNoLimit: true, withCounts: false}).call()
    if (ec.message.hasError()) return
    for (const row of Array.from(out?.rowList || [])) {
        if (row.statusId === 'WeCancelled' || !row.estimatedCompletionDate) continue
        eventList.push({kind: 'task', key: 'task|' + row.workEffortId, workEffortId: row.workEffortId, title: row.workEffortId + ' ' + row.workEffortName,
            start: row.estimatedCompletionDate, end: addDays(row.estimatedCompletionDate, 1), allDay: true, statusId: row.statusId, done: !!row.isDone,
            canEdit: !!row.canUpdate && !row.isDone, movable: true, url: row.url})
    }
})

const record = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
if (record == null) { ec.message.addError(ec.resource.expand(ec.l10n.localize('${id} is not available'), '', {id: workEffortId})); return }
const first = String(start).substring(0, 10)
const params = {workEffortId: workEffortId}
const oldDue = record.estimatedCompletionDate == null ? null : ec.l10n.format(record.estimatedCompletionDate, 'yyyy-MM-dd')
if (record.workEffortTypeEnumId === 'WetTask' || !oldDue) params.dueDay = first
else params.shiftDays = Math.round((Date.parse(first + 'T12:00:00Z') - Date.parse(oldDue + 'T12:00:00Z')) / 86400000)
message = ec.service.sync().name('ironstone.projects.PlanningServices.move#TimelineItem').parameters(params).call()?.message || null

extras = null
const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#PlanItemAccess').parameters({workEffortId: workEffortId, kind: 'milestone', need: 'none'}).call() || {}
if (!access.canView) return
const L = (text) => ec.l10n.localize(text)
const gateOut = ec.service.sync().name('mantle.work.ProjectServices.get#MilestoneApprovalAccess').parameters({workEffortId: workEffortId, need: 'none'}).call() || {}
const gate = gateOut.gate || {required: false}
const projectId = access.plan.rootWorkEffortId
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const nameOf = (partyId) => {
        const party = partyId ? ec.entity.find('mantle.party.PartyDetail').condition('partyId', partyId).one() : null
        return party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || partyId) : ''
    }
    const userName = (userId) => {
        const account = userId ? ec.entity.find('moqui.security.UserAccount').condition('userId', userId).one() : null
        return account ? (account.userFullName || account.username || userId) : ''
    }
    const when = (value) => value == null ? '' : ec.l10n.format(value, 'MMM d, yyyy h:mm a')
    const statusText = (id) => id ? (ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one()?.description || id) : ''
    const requestRow = (row) => ({workEffortApprovalId: row.workEffortApprovalId, statusId: row.statusId, statusText: statusText(row.statusId),
        statusColor: {WeaRequested: 'info', WeaApproved: 'positive', WeaRefused: 'negative', WeaCancelled: 'grey-7'}[row.statusId] || 'grey-7',
        requestedText: when(row.requestedDate), requestedBy: userName(row.requestedByUserId), requestComments: row.requestComments || '',
        decidedText: when(row.decidedDate), decidedBy: userName(row.decidedByUserId) + (row.recordedFor === 'Y' && row.decidedByUserId ? ' ' + L('(recorded for the approver)') : ''),
        decisionComments: row.decisionComments || '', approverName: nameOf(row.approverPartyId),
        fileUrl: row.workEffortContentId ? '/apps/Projects/Projects/MilestoneDetail/estimateFile?workEffortId=' + encodeURIComponent(workEffortId)
            + '&workEffortContentId=' + encodeURIComponent(row.workEffortContentId) : null})
    const requests = Array.from(ec.entity.find('mantle.work.effort.WorkEffortApproval').condition('workEffortId', workEffortId)
            .orderBy('-requestedDate').orderBy('-workEffortApprovalId').limit(20).list()).map(requestRow)
    // who may approve: the project's managers and client contacts (current parties)
    const roles = {ProjectManager: 'Project manager', Manager: 'Manager', ClientManager: 'Client manager', Customer: 'Client', ClientBilling: 'Client billing',
        CustomerBillTo: 'Client bill-to'}
    const approverOptions = []
    for (const row of ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', projectId).condition('roleTypeId', 'in', Object.keys(roles))
            .conditionDate('fromDate', 'thruDate', null).orderBy('roleTypeId').list()) {
        if (approverOptions.some((option) => option.key === row.partyId)) continue
        approverOptions.push({key: row.partyId, text: nameOf(row.partyId) + ' · ' + L(roles[row.roleTypeId])})
    }
    // the estimate file approved by this gate, when it is the project's Estimate milestone
    const estimateId = ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('workEffortId', projectId).condition('settingTypeEnumId', 'WstEstimateMilestone').one()?.settingValue
    const isEstimate = estimateId === workEffortId
    // billing shares, for those who manage money
    const managesMoney = !!ec.service.sync().name('ironstone.projects.BillingServices.check#Money').parameters({need: 'none'}).call()?.managesMoney
    let shareRows = [], lineOptions = [], dueCount = 0
    if (managesMoney) {
        const billing = ec.service.sync().name('mantle.work.ProjectServices.get#MilestoneBilling').parameters({workEffortId: workEffortId}).call() || {}
        ec.message.clearErrors()
        shareRows = Array.from(billing.shareList || []).map((share) => ({orderId: share.orderId, orderItemSeqId: share.orderItemSeqId,
            orderLine: share.orderId + ':' + share.orderItemSeqId, orderUrl: '/qapps/Projects/Billing/OrderDetail?orderId=' + encodeURIComponent(share.orderId),
            lineText: share.orderId + ' ' + share.orderItemSeqId + ' · ' + (share.itemDescription || ''),
            lineTotalText: ec.l10n.formatCurrency(share.lineTotal, share.currencyUomId),
            shareText: share.invoicePercent != null ? ec.l10n.format(share.percent, '#,##0.##') + '%' : L('Fixed'),
            amountText: ec.l10n.formatCurrency(share.amount, share.currencyUomId),
            statusText: share.billed ? ec.resource.expand('Billed on ${invoiceId}', '', {invoiceId: share.invoiceId}) : share.due ? L('Due: ready to invoice')
                : share.awaiting ? L('Waiting for approval') : share.reached ? L('Reached, not approved') : L('When reached'),
            statusColor: share.billed ? 'positive' : share.due ? 'warning' : share.awaiting ? 'info' : 'grey-7', billed: share.billed, due: share.due,
            kind: share.invoicePercent != null ? 'percent' : 'amount', value: share.invoicePercent != null ? String(share.invoicePercent) : String(share.invoiceAmount),
            invoiceUrl: share.invoiceId ? '/qapps/Projects/Billing/InvoiceDetail?invoiceId=' + encodeURIComponent(share.invoiceId) : null}))
        dueCount = shareRows.filter((share) => share.due).length
        const lines = ec.service.sync().name('mantle.work.ProjectServices.get#MilestoneBilling').parameters({rootWorkEffortId: projectId}).call()?.lineList || []
        ec.message.clearErrors()
        lineOptions = Array.from(lines).map((line) => ({key: line.orderId + ':' + line.orderItemSeqId, text: line.orderId + ' ' + line.orderItemSeqId + ' · '
            + (line.description || '') + ' · ' + ec.l10n.formatCurrency(line.total, line.currencyUomId) + ' (' + ec.resource.expand('${shared} shared', '',
                {shared: ec.l10n.formatCurrency(line.sharedAmount, line.currencyUomId)}) + ')'}))
    }
    const deliverables = []
    for (const link of ec.entity.find('mantle.work.effort.WorkEffortDeliverableProd').condition('workEffortId', workEffortId).orderBy('sequenceNum').orderBy('deliverableId').list()) {
        const deliverable = ec.entity.find('mantle.work.effort.Deliverable').condition('deliverableId', link.deliverableId).one()
        if (!deliverable) continue
        deliverables.push({deliverableId: deliverable.deliverableId, deliverableName: deliverable.deliverableName || deliverable.deliverableId,
            typeText: deliverable.deliverableTypeEnumId ? (ec.entity.find('moqui.basic.Enumeration').condition('enumId', deliverable.deliverableTypeEnumId).useCache(true).one()?.description || '') : '',
            deliverableTypeEnumId: deliverable.deliverableTypeEnumId || '', description: deliverable.description || '', accepted: link.acceptedDate != null,
            acceptedText: link.acceptedDate != null ? ec.resource.expand('Accepted ${date} by ${who}', '', {date: ec.l10n.format(link.acceptedDate, 'MMM d, yyyy'),
                who: userName(link.acceptedByUserId)}) : L('Not accepted yet')})
    }
    const latest = requests[0] || null
    extras = {required: !!gate.required, approverPartyId: gate.approverPartyId || '', approverName: gate.approverName || '', awaiting: !!gate.awaiting,
        approved: !!gate.approved, latest: latest, requestRows: requests, isEstimate: isEstimate,
        gateText: !gate.required ? L('No approval needed to reach it') : gate.approved ? L('Approved') : gate.awaiting ? L('Waiting for approval')
            : latest?.statusId === 'WeaRefused' ? L('Refused: ask again when it is fixed') : L('Needs approval to be reached'),
        gateColor: !gate.required ? 'grey-7' : gate.approved ? 'positive' : gate.awaiting ? 'info' : latest?.statusId === 'WeaRefused' ? 'negative' : 'warning',
        canRequest: !!gateOut.canRequest && !!gate.required && !gate.awaiting && !!gate.approverPartyId && !['WeComplete', 'WeClosed', 'WeCancelled'].includes(access.plan.statusId),
        canDecide: !!gateOut.canDecide && !!gate.awaiting, isApprover: !!gateOut.isApprover, canSetGate: !!gateOut.canSetGate, canCancel: !!gateOut.canRequest && !!gate.awaiting,
        approverOptions: approverOptions, managesMoney: managesMoney, shareRows: shareRows, lineOptions: lineOptions, dueCount: dueCount,
        canEditShares: managesMoney && !!access.canManage, canInvoice: managesMoney && !!access.canManage && dueCount > 0,
        deliverables: deliverables, canEditDeliverables: !!access.canUpdate, canAccept: !!gateOut.canDecide}
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

const L = (text) => ec.l10n.localize(text)
const services = {gate: 'store#MilestoneGate', request: 'request#MilestoneApproval', approve: 'approve#MilestoneApproval', refuse: 'refuse#MilestoneApproval',
    cancel: 'cancel#MilestoneApproval'}
if (!services[action]) { ec.message.addError(L('Unknown action')); return }
const parameters = {workEffortId: workEffortId}
if (action === 'gate') { parameters.approvalRequired = approvalRequired === 'Y' ? 'Y' : 'N'; parameters.approverPartyId = approverPartyId ?? null }
else if (action === 'refuse') parameters.reason = comments || null
else if (action !== 'cancel') parameters.comments = comments || null
// the checks of who may do what are Mantle's (get#MilestoneApprovalAccess), with the user's own rights
let out = {}
const wasDisabled = ec.artifactExecution.disableAuthz()
try { out = ec.service.sync().name('mantle.work.ProjectServices.' + services[action]).parameters(parameters).call() || {} }
finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
if (ec.message.hasError()) return
message = {gate: L('Gate saved'), request: L('Approval asked for'), approve: out.projectMoved ? L('Approved: the milestone is reached and the project approved')
    : L('Approved: the milestone is reached'), refuse: L('Refused'), cancel: L('The request is withdrawn')}[action]

const L = (text) => ec.l10n.localize(text)
ec.service.sync().name('ironstone.projects.PlanningServices.get#PlanItemAccess').parameters({workEffortId: workEffortId, kind: 'milestone', need: 'update'}).call()
if (ec.message.hasError()) return
const name = String(deliverableName || '').trim()
if (!name) { ec.message.addError(L('A deliverable needs a name')); return }
if (deliverableTypeEnumId && ec.entity.find('moqui.basic.Enumeration').condition('enumId', deliverableTypeEnumId).condition('enumTypeId', 'DeliverableType').useCache(true).one() == null) {
    ec.message.addError(L('Not a deliverable type')); return }
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    if (deliverableId) {
        if (!ec.entity.find('mantle.work.effort.WorkEffortDeliverableProd').condition({workEffortId: workEffortId, deliverableId: deliverableId}).count()) {
            ec.message.addError(L('Not a deliverable of this milestone')); return }
        ec.service.sync().name('update#mantle.work.effort.Deliverable').parameters({deliverableId: deliverableId, deliverableName: name,
            deliverableTypeEnumId: deliverableTypeEnumId || null, description: description || null}).call()
    } else {
        deliverableId = ec.service.sync().name('create#mantle.work.effort.Deliverable').parameters({deliverableName: name, deliverableTypeEnumId: deliverableTypeEnumId || null,
            description: description || null}).call()?.deliverableId
        const last = Array.from(ec.entity.find('mantle.work.effort.WorkEffortDeliverableProd').condition('workEffortId', workEffortId).orderBy('-sequenceNum').limit(1).list())[0]
        ec.service.sync().name('create#mantle.work.effort.WorkEffortDeliverableProd').parameters({workEffortId: workEffortId, deliverableId: deliverableId,
            sequenceNum: Number(last?.sequenceNum || 0) + 10}).call()
    }
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
if (!ec.message.hasError()) message = ec.resource.expand('Deliverable ${name} saved', '', {name})

const L = (text) => ec.l10n.localize(text)
const access = ec.service.sync().name('ironstone.projects.PlanningServices.get#PlanItemAccess').parameters({workEffortId: workEffortId, kind: 'milestone'}).call() || {}
if (ec.message.hasError()) return
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const link = ec.entity.find('mantle.work.effort.WorkEffortDeliverableProd').condition({workEffortId: workEffortId, deliverableId: deliverableId}).one()
    if (!link) { ec.message.addError(L('Not a deliverable of this milestone')); return }
    if (action === 'remove') {
        if (!access.canUpdate) { ec.message.addError(L('Only the project team changes the deliverables')); return }
        if (link.acceptedDate != null) { ec.message.addError(L('An accepted deliverable stays')); return }
        link.delete()
        message = L('Deliverable taken off')
        return
    }
    const gate = ec.service.sync().name('mantle.work.ProjectServices.get#MilestoneApprovalAccess').parameters({workEffortId: workEffortId, need: 'none'}).call() || {}
    if (!gate.canDecide) { ec.message.addError(L('Only the approver, or one who manages the project for them, accepts a deliverable')); return }
    if (action === 'accept') { link.acceptedDate = ec.user.nowTimestamp; link.acceptedByUserId = ec.user.userId; link.update(); message = L('Deliverable accepted') }
    else if (action === 'unaccept') { link.acceptedDate = null; link.acceptedByUserId = null; link.update(); message = L('Deliverable no longer accepted') }
    else ec.message.addError(L('Unknown action'))
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
